        if limit==1:
            return Node(grid[row][col]==1,True)
        topLeft=self.recurse(grid,row,col,limit//2)
        topRgith=self.recurse(grid,row,col+limit//2,limit//2)
        bottomLeft=self.recurse(grid,row+limit//2,col,limit//2)
        bottomRight=self.recurse(grid,row+limit//2,col+limit//2,limit//2)
